const lead = $json;
const prazo = { 'este-mes': 40, 'proximo-trimestre': 25, pesquisando: 5 };
const porte = { '200+': 25, '51-200': 20, '11-50': 10, '1-10': 5 };
const pessoais = [
  'gmail.com', 'hotmail.com', 'outlook.com', 'yahoo.com.br', 'yahoo.com'
];
const dominio = (lead.email || '').split('@')[1] || '';
const nota = (prazo[lead.prazo] || 0) + (porte[lead.porte] || 0)
  + (dominio && !pessoais.includes(dominio) ? 15 : 0)
  + (lead.whatsapp ? 10 : 0) + (lead.empresa ? 10 : 0);
return { json: {
  ...lead, nota,
  faixa: nota >= 70 ? 'quente' : nota >= 40 ? 'morno' : 'frio',
  etapa: 'Novo lead'
} };

