lead = _item["json"]
prazo = {"este-mes": 40, "proximo-trimestre": 25, "pesquisando": 5}
porte = {"200+": 25, "51-200": 20, "11-50": 10, "1-10": 5}
pessoais = [
    "gmail.com", "hotmail.com", "outlook.com", "yahoo.com.br", "yahoo.com"
]

email = lead.get("email") or ""
dominio = email.split("@")[1] if "@" in email else ""

nota = prazo.get(lead.get("prazo"), 0) + porte.get(lead.get("porte"), 0)
if dominio and dominio not in pessoais:
    nota += 15
if lead.get("whatsapp"):
    nota += 10
if lead.get("empresa"):
    nota += 10

if nota >= 70:
    faixa = "quente"
elif nota >= 40:
    faixa = "morno"
else:
    faixa = "frio"

return {"json": {**lead, "nota": nota, "faixa": faixa, "etapa": "Novo lead"}}
